"Орден собрал все грани Алатыря — и Кощей тут как тут. Теперь во всех Разломах мира — он сам.":"기사단이 알라티르의 모든 면을 모으자 곧바로 코셰이가 나타났어요. 이제 세상의 모든 균열에서 그가 직접 기다리고 있어요.",
