"Орден одолел Кощея — в ярости он расколет камень через {0}":"기사단이 코셰이를 물리쳤어요. 화가 난 그는 {0} 후 돌을 쪼갤 거예요",
"Во всех Разломах мира — Кощей. Одолейте его {0} раз — и он расколет камень раньше; иначе — через {1}.":"세상의 모든 균열에 코셰이가 있어요. 그를 {0}번 물리치면 돌을 더 일찍 쪼개고, 아니면 {1} 후에 쪼개요.",
"Все грани собраны. Финал — через {0}: во всех Разломах мира будет ждать Кощей.":"모든 면을 모았어요. 결전은 {0} 후예요. 세상의 모든 균열에서 코셰이가 기다릴 거예요.",
"Открылась новая мифология — «{0}». Начался сезон {1}.":"새로운 신화 ‘{0}’이(가) 열렸어요. 시즌 {1}이(가) 시작됐어요.",
"Какой мир открылся — Орден узнает с обновлением игры. Начался сезон {0}.":"어떤 세계가 열렸는지는 게임 업데이트 때 기사단이 알게 돼요. 시즌 {0}이(가) 시작됐어요.",
"Эта грань — мифологии, которой ещё нет в игре: она откроется с обновлением. Осколки копятся.":"이 면은 아직 게임에 없는 신화의 것이에요. 업데이트 때 열려요. 조각은 계속 쌓여요.",
"Собрано {0} из {1} — до вехи {2}":"{1}개 중 {0}개를 모았어요. 이정표까지 {2}개 남았어요",
"Духи мифологии «{0}» встречаются в {1} раза чаще. Осталось {2}":"‘{0}’ 신화의 정령이 {1}배 더 자주 나타나요. {2} 남았어요",
"{0} распутывается":"{0}이 풀리고 있어요",
"Грань собрана! Духи мифологии «{0}» станут встречаться чаще через {1}":"한 면을 모았어요! ‘{0}’ 신화의 정령이 {1} 후부터 더 자주 나타나요",
"Мифология сезона {0}. Кощей вот-вот расколет камень — и из трещины выйдет новый мир.":"시즌 {0}의 신화예요. 곧 코셰이가 돌을 쪼개고, 틈새에서 새로운 세계가 나타나요.",
"Мифология сезона {0}. Когда Орден соберёт все {1} граней, Кощей придёт за камнем и расколет его — и из трещины выйдет новый мир.":"시즌 {0}의 신화예요. 기사단이 {1}면을 모두 모으면 코셰이가 돌을 노리고 와서 쪼개요. 그러면 틈새에서 새로운 세계가 나타나요.",
"Множитель Ордена ×{0} — активных Ловчих {1}+ уровня: {2}":"기사단 배율 ×{0} — {1}레벨 이상 활동 사냥꾼: {2}명",
"Чем больше Ловчих {0}+ уровня играли за последние {1} дней, тем дороже новые грани: +{2}% за каждого, но не больше чем вдвое дороже прошлой грани. Цена грани фиксируется, когда грань открывается, и дальше не меняется. «≈» — ориентир для граней, что ещё не открылись.":"최근 {1}일 동안 플레이한 {0}레벨 이상 사냥꾼이 많을수록 새 면이 비싸져요. 한 명당 +{2}%이지만, 이전 면의 두 배를 넘지는 않아요. 면의 가격은 열릴 때 정해지고 그 뒤로는 바뀌지 않아요. ‘≈’는 아직 열리지 않은 면의 예상치예요.",
"Собрана":"모았어요",
"откроется с обновлением игры":"게임 업데이트 때 열려요",
"Мифология сезона {0}: откроется, когда Кощей расколет камень":"시즌 {0}의 신화: 코셰이가 돌을 쪼개면 열려요",
"В сезоне {0} у камня {1} граней — по одной на каждую мифологию. Новая мифология сезона — последняя грань. Всего за сезон — {2} осколков.":"시즌 {0}의 돌은 {1}면이고, 신화마다 한 면씩이에요. 이번 시즌의 새 신화는 마지막 면이에요. 한 시즌에 모두 {2}개의 조각이 필요해요.",
"Награда за сезон":"시즌 보상",
"Принеси в камень хотя бы один осколок — и Орден наградит тебя в конце сезона.":"돌에 조각을 하나라도 가져오세요. 시즌이 끝나면 기사단이 보상을 줘요.",
"До ступени «{0}» — ещё {1}.":"‘{0}’ 단계까지 {1} 남았어요.",
"Награду Орден выдаст, когда Кощей расколет камень, — по вкладу за сезон. Чем больше вклад, тем она щедрее.":"코셰이가 돌을 쪼개면 기사단이 시즌 동안의 기여에 따라 보상을 줘요. 기여가 클수록 보상도 푸짐해요.",
"Сезон {0}":"시즌 {0}",
"Осколков: {0} · побед над Кощеем: {1} (каждая — как {2} осколка)":"조각: {0}개 · 코셰이를 이긴 횟수: {1}번 (한 번이 조각 {2}개)",
"За всё время: {0}":"지금까지: {0}",
"Столько осколков ты принёс Ордену. Они остаются у тебя — для пробуждения духов.":"내가 기사단에 가져온 조각 수예요. 조각은 그대로 내 것이고, 정령 각성에 쓸 수 있어요.",
"сезон {0}":"시즌 {0}",
"Финал сезона {0}: Кощей пришёл за камнем":"시즌 {0} 결전: 코셰이가 돌을 노리고 왔어요",
"Раскол: начался сезон {0}":"쪼개짐: 시즌 {0} 시작",
"побед над Кощеем {0}":"코셰이를 이긴 횟수 {0}번",
"Летопись пока пуста: Орден ещё не собрал ни одной грани.":"기록이 아직 비어 있어요. 기사단이 아직 한 면도 모으지 못했어요.",
"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"어느 사냥꾼이 찾은 알라티르 조각이든, 균열에서든 카피셰의 장로 수호자에게서든, 모두 기사단의 공동 돌에 모여요. 한 면이 모이면 그 세계로 가는 길이 풀려요. {0}일 동안 그 신화의 정령이 모든 사냥꾼에게 동시에 {1}배 더 자주 나타나요. 시즌의 모든 면이 모이면 코셰이가 와요. {2}일 동안 세상의 모든 균열에서 기다리다가 돌을 쪼개요. 틈새에서 새로운 신화가 나오고 새 시즌이 시작돼요. 리그도 마찬가지예요. 새 시즌의 돌은 면이 하나 더 많아요.",
"Духолов":"두홀로프",
"Смотри, кого я поймал в Духолове!":"두홀로프에서 내가 잡은 정령 좀 봐!",
"Снимок сохранён":"사진을 저장했어요",
"Снимок":"사진",
"Снимок духа":"정령 사진",
