"Быстрота и отвага":"신속과 용기",
"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Капищ и держат Навь громом Перуна.":"매 라로그의 문장을 내건 공후 친위대의 후예. 코셰이가 알라티르를 깨뜨렸을 때 가장 먼저 카피셰 앞에 섰고, 페룬의 천둥으로 나브를 막아 내고 있어요.",
"Фаланга Олимпа":"올림포스 팔랑크스",
"Сова":"올빼미",
"гоплит":"호플리테스",
"Щит к щиту":"방패와 방패를 맞대고",
"Ловчие, что сомкнули щиты под знаком совы Афины. В Перепутицу они стерегут храмы, чтобы тени Аида не вышли к живым.":"아테나의 올빼미 문장 아래 방패를 맞댄 사냥꾼들. 대혼선 속에서 하데스의 그림자가 산 자들에게 나오지 못하도록 신전을 지켜요.",
"Хирд Асгарда":"아스가르드 히르드",
"Волк":"늑대",
"хирдман":"히르드만",
"Верность и чутьё":"충성과 직감",
"Верные, как волки Одина. Хирд стоит у рунных камней, пока не затянутся трещины к Гиннунгагапу.":"오딘의 늑대처럼 충직해요. 긴능가가프로 이어진 균열이 닫힐 때까지 히르드는 룬스톤 곁을 지켜요.",
"Братство Дуба":"참나무 형제단",
"Медведь":"곰",
"друид":"드루이드",
"Сила и стойкость":"힘과 인내",
"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"암곰 아르티오의 보호를 받는 신성한 숲의 드루이드와 전사들. 형제단은 요정 언덕이 영영 열려 버리지 않도록 환상열석을 지켜요.",
"Стражи Дуата":"두아트의 수호자",
"Скарабей":"스카라베",
"страж":"수호자",
"Солнце взойдёт снова":"해는 다시 떠오른다",
"Хранители солнечной ладьи Ра. Пока Алатырь расколот, стражи стоят у обелисков, чтобы ночь Дуата не поглотила рассвет.":"라의 태양 배를 지키는 이들. 알라티르가 깨져 있는 동안 수호자들은 두아트의 밤이 새벽을 삼키지 못하도록 오벨리스크 곁을 지켜요.",
"Небесная Гвардия":"천상의 근위대",
"Дракон":"용",
"гвардеец":"근위병",
"Небо и земля в равновесии":"하늘과 땅의 균형",
"Воины под знаменем Лазурного дракона. В Перепутицу гвардия держит пагоды, чтобы Небесные врата не остались распахнутыми.":"청룡의 깃발 아래 모인 전사들. 대혼선 속에서 하늘의 문이 활짝 열린 채로 남지 않도록 근위대가 탑을 지켜요.",
"Орден Ягуара":"재규어 전사단",
"Ягуар":"재규어",
"воин-ягуар":"재규어 전사",
"Солнце не должно погаснуть":"태양이 꺼져선 안 된다",
"Самые отважные воины древних городов Америки. Орден держит пирамиды, чтобы из Миктлана не пришла вечная ночь.":"아메리카 고대 도시들에서 가장 용맹한 전사들. 믹틀란에서 영원한 밤이 찾아오지 않도록 전사단이 피라미드를 지켜요.",
"Клан «{0}»":"‘{0}’ 클랜",
"воин клана":"클랜 전사",
"Вместе — за Алатырь":"알라티르를 위해 함께",
"Ловчие мифологии «{0}»: они держат её святилища, пока Алатырь расколот.":"‘{0}’ 신화의 사냥꾼들. 알라티르가 깨져 있는 동안 그 성소를 지켜요.",
"Ученик":"견습",
"Мастер":"명인",
"Старейшина":"장로",
"Святки":"스뱟키",
"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"겨울 명절: 모로즈코와 스네구르카가 사람들 곁으로 나오고, 바람과 물 정령이 더 자주 나타나며, 원천에서 선물이 나와요.",
"Масленица":"마슬레니차",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"겨울을 보내요! 불 정령이 두 배로 자주 나타나고, 원천에서 꿀(‘블리니’)이 잔뜩 나오며, 경험치 ×1.5.",
"Купальская ночь":"쿠팔라의 밤",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"고사리꽃이 피어요: 쿠팔린카가 어디에나 있고, 불·물·숲 정령이 더 자주, 밤에는 빛나는 정령이 두 배로 자주 나타나요.",
"Покров":"포크로프",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"첫 안개와 서리: 바람과 물 정령이 더 자주 나타나고, 리스토파드니차가 어디에나 있으며, 원천에서 전리품이 더 많이 나와요.",
"Велесова ночь":"벨레스의 밤",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"두 세계의 경계가 가장 얇아요: 그림자 정령이 세 배로 자주 나타나고, 대균열에는 코셰이가 기다리며, 빛나는 그림자 정령이 두 배로 자주 나타나요.",
"Этот источник теперь принадлежит Нави!":"이 원천은 이제 나브의 것이다!",
"Твои духи будут служить Кощею!":"네 정령들은 코셰이를 섬기게 될 거다!",
"Орден Оберега? Никогда о таком не слышал.":"부적 기사단? 처음 듣는데.",
"Граница рухнет, и мы заберём весь город!":"경계가 무너지면 이 도시는 전부 우리 차지다!",
"Думаешь, оберегом меня остановишь?":"부적 따위로 날 막을 수 있을 것 같나?",
"Тьма уже здесь, Ловчий. Смирись.":"어둠은 이미 여기 있다, 사냥꾼. 받아들여라.",
