"Дружба: {0} ({1} ★)":"우정: {0} ({1} ★)",
"Спасибо!":"고마워요!",
"Дарите подарки и сражайтесь вместе":"선물을 주고받고 함께 싸워요",
"ДРУЗЕЙ":"친구",
"Подарков в сумке: {0}":"가방 속 선물: {0}",
"Позвать":"초대",
"Позвать друга по ссылке":"링크로 친구 초대",
"откроет ссылку — и вы сразу друзья, обоим подарки":"링크를 열면 바로 친구가 되고, 둘 다 선물을 받아요",
"Мой QR-код":"내 QR 코드",
"Мой код дружбы":"내 우정 코드",
"или код друга":"또는 친구 코드",
"Сканировать QR-код":"QR 코드 스캔",
"Вставь код: DUHF1…":"코드 붙여넣기: DUHF1…",
"Добавить по коду":"코드로 추가",
"Достаточно, чтобы один из вас добавил код другого, — дружба станет взаимной.":"한 명만 상대의 코드를 추가하면 서로 친구가 돼요.",
"Друг у разлома нажал «Позвать друзей» и прислал код из 5 символов? Введи его — и в бой вместе, где бы ты ни был.":"균열 앞의 친구가 ‘친구 부르기’로 5자리 코드를 보냈나요? 입력하면 어디에 있든 함께 싸울 수 있어요.",
"КОД":"코드",
"пришло подарков: {0}":"도착한 선물: {0}",
"подарок каждому другу — раз в день":"친구마다 하루 한 번 선물",
"Подарки от друзей":"친구가 보낸 선물",
