"Это ты":"나",
"Так твою карточку видят другие Ловчие.":"다른 사냥꾼에게 내 카드는 이렇게 보여요.",
"Хочет с тобой дружить":"친구 요청을 보냈어요",
"Не в друзьях":"친구 아님",
"Друзья обмениваются подарками и сражаются в поединках. Дружба растёт от подарков, поединков и совместных разломов.":"친구끼리 선물을 주고받고 결투할 수 있어요. 선물, 결투, 협동 균열로 우정이 깊어져요.",
