"Ждём, когда добавит в ответ":"상대가 수락하길 기다리는 중",
"Заявка отправлена":"요청 보냄",
"Принять дружбу":"친구 수락",
"Добавить в друзья":"친구 추가",
"{0} Ордена Оберега":"부적 기사단 {0}",
