"Неверный приём":"잘못된 기술",
"Этого духа не выпустить":"이 정령은 내보낼 수 없어요",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"링이 줄어들 때 부적을 던지세요. ‘훌륭해요!’가 뜨면 경험치와 포획 확률이 올라가요.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"원천은 몇 분 뒤 다시 차올라요. 한 바퀴 산책하면 물자가 쌓여요.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"파트너는 함께 걸으며 자기 계열의 정수를 찾아 줘요.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"리그에서는 실제 사냥꾼끼리 싸워요: 강한 상대를 이기면 약한 상대보다 레이팅이 더 올라요.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"균열은 매시간 카피셰 곁에 열려요. 정령 셋으로 팀을 꾸리세요.",
"Сияющие духи редки — их выдают искры вокруг.":"빛나는 정령은 드물어요. 주위에 반짝이는 불꽃으로 알아볼 수 있어요.",
"Коконы греются шагами: одновременно можно греть три.":"고치는 걸음으로 데워져요. 동시에 세 개까지 데울 수 있어요.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"조이스틱으로 움직이세요: 살짝 기울이면 걷기, 끝까지 밀면 달리기예요. 고치 거리도 똑같이 계산돼요.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"세계 지도책은 30분마다 한 번 지구 어디로든 데려다줘요. ‘대혼선의 문’은 바로 이동해요.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"오늘의 퀘스트는 자정에 바뀌고, 세 개를 모두 끝내면 오늘의 상자가 기다려요.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"우리 클랜의 카피셰에 방어자를 세우면 불꽃을 가져와요.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"날씨는 해당 속성의 정령을 강하게 해요. 비가 오면 물 정령이 더 자주 나와요.",
