"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"그 사냥꾼에게는 다른 로그인 방법이 있어서 진행 상황은 그대로 이용할 수 있어요.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>그 사냥꾼에게는 다른 로그인 방법이 없어서 진행 상황이 영원히 사라져요.</b>",
