"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"그 계정으로 전환할 수 있어요 — 현재 진행 상황은 그대로 남아요. 또는 이 로그인을 현재 사냥꾼에게 연결하세요.",
