"Другой аккаунт":"다른 계정",
"Гость играет только на этом устройстве — привяжи вход, чтобы не потерять прогресс":"게스트는 이 기기에서만 플레이할 수 있어요. 로그인을 연결해 진행 상황을 지키세요",
"Привяжи вход — и прогресс откроется на любом устройстве":"로그인을 연결하면 어느 기기에서든 진행 상황을 이어갈 수 있어요",
"Текущий прогресс останется в своей учётной записи":"현재 진행 상황은 원래 계정에 그대로 남아요",
