"Выйти?":"로그아웃할까요?",
"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"진행 상황은 계정에 남아요. 같은 방법으로 로그인하면 돌아올 수 있어요. 이 기기에서는 새 게스트 게임이 시작돼요.",
