"Выйти из гостевой игры?":"게스트 게임에서 나갈까요?",
"<b>Прогресс гостя пропадёт навсегда</b> — у гостя нет входа, чтобы вернуться.":"<b>게스트 진행 상황은 영구히 사라져요</b>. 게스트는 다시 돌아올 로그인 수단이 없어요.",
"Чтобы сохранить его, сначала привяжи вход через {0}.":"지키려면 먼저 {0} 로그인을 연결하세요.",
"Выхожу…":"로그아웃 중…",
"Нет связи с Навью":"나브와 연결할 수 없어요",
"Не удалось загрузить карту. Проверь подключение к интернету.":"지도를 불러오지 못했어요. 인터넷 연결을 확인하세요.",
"Повторить":"다시 시도",
"{0} готов вылупиться!":"{0} 부화 준비 완료!",
"Коконов готово: {0}. Загляни в меню!":"부화할 고치: {0}개. 메뉴를 확인하세요!",
"Прогресс хранится на сервере игры, поэтому нужен интернет.":"진행 상황은 게임 서버에 저장되므로 인터넷이 필요해요.",
"Проверяю обновления…":"업데이트 확인 중…",
