"Прогресс загружен":"진행 상황을 불러왔어요",
"Не получилось запустить игру":"게임을 시작하지 못했어요",
"Проверь подключение к интернету и попробуй ещё раз.":"인터넷 연결을 확인하고 다시 시도하세요.",
"С":"북",
"В":"동",
"Ю":"남",
"З":"서",
"{0}: {1}. Подойди ближе — нужно {2} м":"{0}: {1}. 더 가까이 가세요. {2}m 안에 있어야 해요",
