"Узнаём, как идут дела у Ордена…":"기사단 소식을 확인하는 중…",
"поимка духа стихии «{0}» — 3 очка":"‘{0}’ 속성 정령 포획 — 3포인트",
"источник — 2 очка":"원천 — 2포인트",
"разлом — 10 очков":"균열 — 10포인트",
"победа в капище — 6 очков":"카피셰 승리 — 6포인트",
"путь и коконы — вдвое":"걸음과 고치 — 2배",
"Прошлая неделя — награды ещё ждут":"지난주 — 보상이 아직 기다려요",
"Все Ловчие вместе копят очки: {0}.":"모든 사냥꾼이 함께 포인트를 모아요: {0}.",
" На этой неделе {0}.":" 이번 주: {0}.",
"Цель растёт с числом участников. Награду ступени получает каждый, кто внёс нужное число очков.":"참가자가 많을수록 목표도 커져요. 필요한 포인트를 기여한 사람은 누구나 단계 보상을 받아요.",
"{0} распутана — ещё {1}":"{0}이 풀렸어요. {1} 남았어요",
"Орден собрал {0} осколков · до вехи {1}":"기사단이 조각 {0}개를 모았어요 · 이정표까지 {1}개",
"Общий камень Ордена: каждая грань распутывает дорогу в один из миров":"기사단의 공동 돌: 면 하나마다 한 세계로 가는 길이 풀려요",
