"Следопыт":"추적자",
"Ведун":"현자",
"Хранитель":"수호자",
"Поимка духов":"정령 포획",
"Обереги, мёд, источники и коконы":"부적, 꿀, 원천, 고치",
"Задания дня и поручения источников":"오늘의 퀘스트와 원천의 의뢰",
"Лавка Ордена":"기사단 상점",
"Обереги, мёд и живая вода":"부적, 꿀, 지바야 보다",
"Коды дружбы и ежедневные подарки":"우정 코드와 매일 선물",
"Награды за обычную игру":"평소 플레이 보상",
"Бой командой из трёх духов с хранителем Разлома":"정령 세 마리 팀으로 균열 수호자와 전투",
"Капища предков":"조상의 카피셰",
"Поединки 3 на 3 с хранителями":"수호자와의 3대3 결투",
