"Сегодня получено {0} опыта — дальше вполовину до {1}":"오늘 얻은 경험치 {0} — 이제 {1}까지는 절반",
"Сегодня получено {0} опыта — дальше на четверть":"오늘 얻은 경험치 {0} — 이제부터는 4분의 1",
"Опыт отдыха: следующие {0} опыта — вдвое":"휴식 경험치: 다음 경험치 {0}은(는) 두 배",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"하루 경험치는 {0}까지 전부, {1}까지는 절반, 그 이상은 4분의 1만 들어와요. 튜토리얼과 기사단 배지의 경험치는 언제나 전부 들어와요. 게임을 쉰 날마다 휴식 경험치가 쌓여요({2}, 최대 {3}{4}치): 휴식 경험치가 남아 있는 동안 경험치가 두 배예요.",
