"Ты прошёл весь путь!":"모든 여정을 마쳤어요!",
"До {0} уровня — {1} опыта":"레벨 {0}까지 경험치 {1}",
"дальше: {0} на {1}":"다음: Lv.{1}에 {0}",
"Опыт дают поимки, источники, разломы, капища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"경험치는 포획, 원천, 균열, 카피셰, 퀘스트로 얻어요. 레벨이 오르면 정령도 성장해요: 사냥꾼 레벨 +5까지 강화할 수 있어요.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"레벨 {0}부터 정령을 각성시킬 수 있어요: 별 하나마다 정령의 레벨 한계가 {1}씩 올라 최대 {2}까지 높아져요.",
"Ищу настоящие места вокруг — Источники и Капища появятся через несколько секунд":"주변의 실제 장소를 찾는 중이에요. 곧 원천과 카피셰가 나타나요",
"Посылка из Ордена":"기사단의 소포",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"근처에 아직 원천이 없어서, 기사단이 하루에 한 번 물자를 보내 줘요: {0}.",
"Спасибо":"고마워요",
"На проверке":"검토 중",
"Одобрено":"승인됨",
"Отклонено":"거절됨",
"Места":"장소",
"Источники и Капища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"원천과 카피셰는 실제 장소에 있어요. 근처에 흥미로운 곳을 알고 있나요? 제안해 주세요!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>가능:</b> 기념비, 조각상, 분수, 모자이크, 독특한 건물, 사원, 공원, 샘터, 전망대.",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>불가:</b> 개인 주택과 마당, 학교와 유치원, 위험한 곳(차도, 공사장), 일반 상점.",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"대상 가까이에 서 주세요. 사진에 위치 정보가 기록되고, 운영자가 지도 위 지점과 대조해요.",
"Сфотографировать объект":"대상 촬영하기",
