"Точка объекта":"대상 위치",
"Круг — {0} м от места, где ты стоишь на карте. Перетащи булавку точно на объект.":"원은 지도에서 네가 서 있는 곳에서 {0}m 범위예요. 핀을 대상 위에 정확히 끌어다 놓으세요.",
