"закроется через {0}":"{0} 후 닫힘",
"Босс":"보스",
"Этот разлом ты уже закрыл. Новый босс — в начале следующего часа.":"이 균열은 이미 닫았어요. 새 보스는 다음 정각에 나타나요.",
