"Разломов закрыто":"닫은 균열",
"Слабость":"약점",
"урон +20% у {0}":"{0} 피해 +20%",
"Уровень босса":"보스 레벨",
"растёт с уровнем Ловчего":"사냥꾼 레벨에 따라 올라요",
