"Бей в слабость: духи этих стихий наносят больше урона. Тап — атака, смахни в сторону — уклон от удара босса.":"약점을 노려요: 이 속성의 정령이 더 큰 피해를 줘요. 탭 — 공격, 옆으로 밀기 — 보스의 공격 회피.",
"Опыт":"경험치",
" · с друзьями +25%":" · 친구와 함께 +25%",
