"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"알라티르가 갈라진 곳에서 대혼선의 물이 땅에서 솟아요. 온 땅의 사냥꾼들이 원천에서 부적과 보급품을 길어 가요.",
