"Дальше":"다음",
"Выбери первого духа":"첫 정령을 고르세요",
"Он будет с тобой с первого дня.":"첫날부터 함께할 정령이에요.",
"Весь мир — твой":"온 세상이 네 거예요",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"대혼선이 세상의 길을 뒤엉키게 하자 부적 기사단이 사냥꾼들에게 문을 열었어요: 세계 지도책에서 지구의 어느 곳이든 고르세요 — 거기서 사냥이 시작돼요. 지도에서는 조이스틱으로 걷고, 새로운 땅으로는 지도책을 통해 건너가요. 게임에는 휴대폰의 실제 위치가 필요 없어요. 진행 상황은 게임 서버에 저장되고 너만 볼 수 있어요; 서버가 모든 행동을 확인하므로 인터넷이 필요해요. 고른 지역의 지도 장소와 날씨는 OpenStreetMap과 Open-Meteo에서 불러와요(날씨는 설정에서 끌 수 있어요).",
"В путь":"출발",
"Уже играешь?":"이미 하고 있나요?",
"Войди — и твой прогресс откроется на этом устройстве":"로그인하면 이 기기에서 진행 상황을 이어갈 수 있어요",
"Назови себя":"이름을 입력하세요",
"Новое приложение":"새 앱",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"게임이 러시아의 자체 서버 <b>duholov.ru</b>로 이전했어요. 그래서 새 앱이 나왔고, 다시 설치해야 해요.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"로그인을 연결하세요: 메뉴 → 설정 → 계정 (Google, 얀덱스, VK, Telegram 또는 이메일). 연결하지 않으면 게스트 진행 상황이 옮겨지지 않아요.",
"Удали это приложение.":"이 앱을 삭제하세요.",
"Скачай и установи новое — войди тем же способом.":"새 앱을 다운로드해 설치하고, 같은 방법으로 로그인하세요.",
